pub(crate) fn it_stored_block(mut z: &mut crate::port::Cells, n: i32) -> i32 {
    // A non-final stored block of n bytes, the byte at i being i * 7 + i / 256.
    let mut i: i32 = 0;
    crate::port::cells_push(z, 0);
    crate::port::cells_push(z, n & 255);
    crate::port::cells_push(z, n / 256);
    crate::port::cells_push(z, (65535 - n) & 255);
    crate::port::cells_push(z, (65535 - n) / 256);
    while i < n {
        crate::port::cells_push(z, ((i * 7) + (i / 256)) & 255);
        i += 1;
    }
    return 0;
}
