#[test]
fn test_the_maximum_distance() {
    // 32768 stored bytes, then a fixed block that copies three bytes from
    // distance 32768 (symbol 29, all 13 extra bits set): the very first three.
    // With one byte less of history the same copy reaches too far back.
    let z: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    it_stored_block(z, 32768);
    it_push_blob(z, &crate::testport::hex_blob("03deff0f00")[..]);
    crate::testport::assert_eq(iz_raw(&crate::testport::cells_blob(z)[..], 0, crate::port::cells_len(z), out, st), iz_ok(), "status");
    crate::testport::assert_eq(iz_consumed(st), crate::port::cells_len(z), "consumed");
    crate::testport::assert_eq(crate::port::cells_len(out), 32771, "length");
    crate::testport::assert_eq(crate::port::cells_at(out, 32768), crate::port::cells_at(out, 0), "first copied byte");
    crate::testport::assert_eq(crate::port::cells_at(out, 32769), crate::port::cells_at(out, 1), "second");
    crate::testport::assert_eq(crate::port::cells_at(out, 32770), crate::port::cells_at(out, 2), "third");
    crate::testport::assert_eq(crate::port::cells_at(out, 32767), ((32767 * 7) + 127) & 255, "the last stored byte");
    crate::port::cells_drop(z, 0);
    crate::port::cells_drop(out, 0);
    it_stored_block(z, 32767);
    it_push_blob(z, &crate::testport::hex_blob("03deff0f00")[..]);
    crate::testport::assert_eq(iz_raw(&crate::testport::cells_blob(z)[..], 0, crate::port::cells_len(z), out, st), iz_bad_distance(), "too far back");
    crate::testport::assert_eq(crate::port::cells_len(out), 32767, "the stored bytes are kept");
}
